insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('961a4f92-dec1-44c3-9652-9fa869d14f30', '543c3607-0021-4864-aca4-912c8ab60fd4', $$f(x) = x⁵ − 3x√x$$,
   $$wiskunde-b-vwo-2024-i-stijgend-en-horizontaal-context1.png$$,
   $$De functie f wordt gegeven door f(x) = x⁵ − 3x√x.
In figuur 1 is de grafiek van f weergegeven.$$, 'inline'),
  ('d47057f5-4b71-4ddc-86d8-a4e693a3fe33', '543c3607-0021-4864-aca4-912c8ab60fd4', $$figuur 1: grafiek van f$$,
   $$wiskunde-b-vwo-2024-i-stijgend-en-horizontaal-context2.png$$,
   $$figuur 1: de grafiek van f$$, 'inline'),
  ('08af8ad0-a705-4ba0-b9bd-58e56fbbbe25', '543c3607-0021-4864-aca4-912c8ab60fd4', $$punt A(1, −2) op de grafiek$$,
   $$wiskunde-b-vwo-2024-i-stijgend-en-horizontaal-context3.png$$,
   $$Op de grafiek ligt het punt A(1, −2).$$, 'inline'),
  ('93d33854-3a05-4c30-98fa-5ddd09e46aa4', '543c3607-0021-4864-aca4-912c8ab60fd4', $$horizontaal lijnstuk PQ met lengte ½ met eindpunten op de grafiek$$,
   $$wiskunde-b-vwo-2024-i-stijgend-en-horizontaal-context4.png$$,
   $$Het lijnstuk PQ is horizontaal en heeft lengte ½.
De eindpunten P en Q van dit lijnstuk liggen op de grafiek van f.
Zie figuur 2.$$, 'inline'),
  ('0fd2cffa-dd4b-4dc9-9eb6-da0ddf04dd1c', '543c3607-0021-4864-aca4-912c8ab60fd4', $$figuur 2: grafiek van f met lijnstuk PQ$$,
   $$wiskunde-b-vwo-2024-i-stijgend-en-horizontaal-context5.png$$,
   $$figuur 2: de grafiek van f met het horizontale lijnstuk PQ met lengte ½$$, 'inline'),
  ('b6c28ba5-e67e-4269-98f7-4e06051352ad', '9fa2639f-145c-42d1-b83d-c507fbee9b9d', $$inleiding: wachttijden en het model van Erlang$$,
   $$wiskunde-b-vwo-2024-i-wachttijden-context1.png$$,
   $$Een wachttijd is de tijd die je op een dienst moet wachten. Denk hierbij bijvoorbeeld aan de tijd die nodig is om een medewerker van een klantenservice aan de telefoon te krijgen of de tijd die nodig is voordat je wordt geholpen bij de bakker.
In 1909 ontwikkelde de Deense wiskundige Agner Erlang een wiskundig model om te berekenen in hoeveel procent van de gevallen bepaalde wachttijden voorkomen. Dit percentage komt overeen met de oppervlakte onder een grafiek.$$, 'inline'),
  ('bbd3fd07-fc68-46c6-b975-cdccf4ab47af', '9fa2639f-145c-42d1-b83d-c507fbee9b9d', $$model f(t) = 50e^(−½t) met t ≥ 0, t in minuten$$,
   $$wiskunde-b-vwo-2024-i-wachttijden-context2.png$$,
   $$In deze opgave gaan we uit van een dienst waarbij het volgende model van Erlang hoort:
f(t) = 50e^(−½t) met t ≥ 0
Hierbij is t de tijd in minuten.$$, 'inline'),
  ('ab70af3b-5add-4089-abe0-81f937fb2417', '9fa2639f-145c-42d1-b83d-c507fbee9b9d', $$oppervlakte tussen t = 3 en t = 4 is 8,8: percentage wachttijden$$,
   $$wiskunde-b-vwo-2024-i-wachttijden-context3.png$$,
   $$Stel dat je wilt weten in hoeveel procent van de gevallen de wachttijd tussen 3 en 4 minuten ligt. Je bepaalt dan de oppervlakte van het gebied dat wordt ingesloten door de grafiek van f, de t as en de lijnen met vergelijking t = 3 en t = 4. Deze oppervlakte blijkt (afgerond) 8,8 te zijn. Dit wil zeggen dat in 8,8% van alle gevallen de wachttijd tussen 3 en 4 minuten ligt. Zie de figuur.$$, 'inline'),
  ('19cdf73b-ef80-4f13-9cdc-dbd04f9a6328', '9fa2639f-145c-42d1-b83d-c507fbee9b9d', $$figuur: grafiek van f met grijs vlakdeel tussen t = 3 en t = 4$$,
   $$wiskunde-b-vwo-2024-i-wachttijden-context4.png$$,
   $$figuur: de grafiek van f met het grijze vlakdeel tussen t = 3 en t = 4$$, 'inline'),
  ('dc4911a0-7c63-4b86-9f8b-0013ee2aabef', '9fa2639f-145c-42d1-b83d-c507fbee9b9d', $$gemiddelde wachttijd (1/100) · ∫₀²⁰ t · f(t) dt en primitieve van y = teᵃᵗ$$,
   $$wiskunde-b-vwo-2024-i-wachttijden-context5.png$$,
   $$Een wachttijd van meer dan twintig minuten komt in dit voorbeeld zelden voor. Daarom wordt de gemiddelde wachttijd berekend met:
(1/100) · ∫₀²⁰ t · f(t) dt
Om de gemiddelde wachttijd te kunnen berekenen, maakt iemand gebruik van het gegeven dat y = ((1/a)t − 1/a²) · eᵃᵗ een primitieve is van y = teᵃᵗ (met a ≠ 0).$$, 'inline'),
  ('230aff41-b5f5-44de-8084-af4ad8c867ce', 'ade0818d-4432-4d3b-a3a6-0de200e6cdfd', $$f(x) = (3x − 7)²; g ontstaat door verschuiving naar rechts en omhoog; g gaat door A(5, 40) met helling −6$$,
   $$wiskunde-b-vwo-2024-i-verschuiven-context1.png$$,
   $$De functie f wordt gegeven door f(x) = (3x − 7)².
De grafiek van f wordt naar rechts en omhoog verschoven. Hierdoor ontstaat de grafiek van de functie g.
De grafiek van g gaat door het punt A(5, 40). De helling van de raaklijn in A aan de grafiek van g is −6.$$, 'inline'),
  ('c0ea23de-92c2-4995-bb13-cd08c0d4401f', '3cc8402b-94d5-4b04-989c-daeaf3b0995f', $$f(x) = ²log(√(1 + 8ˣ))$$,
   $$wiskunde-b-vwo-2024-i-logaritme-wortel-en-exponent-context1.png$$,
   $$De functie f wordt gegeven door f(x) = ²log(√(1 + 8ˣ)).$$, 'inline'),
  ('5d74f9b3-db57-4727-90f6-606b9dc652fa', '3cc8402b-94d5-4b04-989c-daeaf3b0995f', $$g is de inverse functie van f; figuur met de grafieken van f en g$$,
   $$wiskunde-b-vwo-2024-i-logaritme-wortel-en-exponent-context2.png$$,
   $$De functie g is de inverse functie van f.
In de figuur zijn de grafieken van f en g weergegeven.
figuur: de grafieken van f en g met een gestippeld verticaal lijnstuk ertussen$$, 'inline'),
  ('aaa814c2-f1b4-46bb-b4d4-b366e4ca0b9d', '3cc8402b-94d5-4b04-989c-daeaf3b0995f', $$kortst mogelijke verticale lijnstuk tussen de grafieken van f en g$$,
   $$wiskunde-b-vwo-2024-i-logaritme-wortel-en-exponent-context3.png$$,
   $$Het gestippelde lijnstuk in de figuur is het kortst mogelijke verticale lijnstuk dat de grafieken van f en g met elkaar verbindt.$$, 'inline'),
  ('6667d2ac-d0f5-4e75-873a-aca76a20d50e', '3cc8402b-94d5-4b04-989c-daeaf3b0995f', $$punten P en Q op de grafiek van f met x-coördinaten p en p + 1; verschil y_Q − y_P$$,
   $$wiskunde-b-vwo-2024-i-logaritme-wortel-en-exponent-context4.png$$,
   $$Op de grafiek van f ligt punt P met x-coördinaat p en punt Q met x-coördinaat p + 1. Voor elke waarde van p kan het verschil y_Q − y_P worden bepaald.$$, 'inline'),
  ('769e2b8a-3b4f-4033-a6eb-462b735bb56f', '29e9e84f-1f33-44d3-968d-e2faa36cc7f4', $$bewegingsvergelijkingen van P: x_P(t) = 4cos(t) + cos(4t), y_P(t) = 4sin(t) + sin(4t)$$,
   $$wiskunde-b-vwo-2024-i-klavertje-drie-context1.png$$,
   $$Het punt P beweegt over een baan gegeven door de volgende bewegingsvergelijkingen:
x_P(t) = 4cos(t) + cos(4t)
y_P(t) = 4sin(t) + sin(4t)
met t in seconden en 0 ≤ t ≤ 2π
De baan waarover punt P beweegt, is weergegeven in de figuur.$$, 'inline'),
  ('30ade45c-880b-47ad-a007-06e1975ab05f', '29e9e84f-1f33-44d3-968d-e2faa36cc7f4', $$Q loopt π seconden voor op P: bewegingsvergelijkingen van Q$$,
   $$wiskunde-b-vwo-2024-i-klavertje-drie-context2.png$$,
   $$Het punt Q beweegt ook over deze baan. Punt Q loopt π seconden voor op punt P. De bewegingsvergelijkingen van Q zijn dus:
x_Q(t) = 4cos(t + π) + cos(4(t + π))
y_Q(t) = 4sin(t + π) + sin(4(t + π))
met t in seconden en 0 ≤ t ≤ 2π$$, 'inline'),
  ('e755794c-e861-40d3-99e9-5c8650310e9a', '29e9e84f-1f33-44d3-968d-e2faa36cc7f4', $$P en Q recht boven elkaar: x_P = x_Q$$,
   $$wiskunde-b-vwo-2024-i-klavertje-drie-context3.png$$,
   $$Er zijn twee momenten waarop P en Q recht boven elkaar liggen, dus dan geldt x_P = x_Q. In de figuur is zo''n situatie weergegeven.$$, 'inline'),
  ('c3ccd63b-8554-469b-b68b-fbe812890fd8', '29e9e84f-1f33-44d3-968d-e2faa36cc7f4', $$figuur: de baan met P en Q recht boven elkaar$$,
   $$wiskunde-b-vwo-2024-i-klavertje-drie-context4.png$$,
   $$figuur: de baan (klavertje drie) met P en Q recht boven elkaar op een gestippelde verticale lijn$$, 'inline'),
  ('b4a31685-3454-4170-a642-4bb8fbcdce7a', '29e9e84f-1f33-44d3-968d-e2faa36cc7f4', $$op t = ⅔π is P in (−2½, 2½√3)$$,
   $$wiskunde-b-vwo-2024-i-klavertje-drie-context5.png$$,
   $$Op tijdstip t = ⅔π bevindt het punt P zich in (−2½, 2½√3).$$, 'inline'),
  ('4b88289c-fa3c-4b03-a6dc-41709b55c7ed', '45613080-fcd9-496b-829e-fe27417fec11', $$A(−1, 0), B(3, 0), cirkel c met middellijn AB; lijn k door O snijdt c in P met OP = 2½$$,
   $$wiskunde-b-vwo-2024-i-halve-cirkel-context1.png$$,
   $$Gegeven zijn de punten A(−1, 0) en B(3, 0). Verder is gegeven de cirkel c met middellijn AB. De lijn k gaat door de oorsprong O en snijdt cirkel c in punt P. De afstand tussen O en P is gelijk is aan 2½. In figuur 1 zijn lijn k en de bovenste helft van cirkel c getekend.$$, 'inline'),
  ('7f17ca45-e96b-4c3a-985a-e60c867f1585', '45613080-fcd9-496b-829e-fe27417fec11', $$figuur 1: lijn k en de bovenste helft van cirkel c$$,
   $$wiskunde-b-vwo-2024-i-halve-cirkel-context2.png$$,
   $$figuur 1: de bovenste helft van cirkel c en lijn k door O en P$$, 'inline'),
  ('69412b51-febb-4305-a13c-db40b54f7dcc', '45613080-fcd9-496b-829e-fe27417fec11', $$driehoek BRO met ∠BRO = 90°, OR = 1; BR snijdt c in S; vierhoek AORS$$,
   $$wiskunde-b-vwo-2024-i-halve-cirkel-context3.png$$,
   $$In figuur 2 is de driehoek BRO getekend met ∠BRO = 90°, punt R boven de x-as en OR = 1. De lijn door B en R snijdt c in het punt S. Driehoek BSA is dan een driehoek met ∠ASB = 90°. Vierhoek AORS is grijs weergegeven.$$, 'inline'),
  ('8e7f8bcc-5267-4bff-bed8-f23f2dc6bb37', '45613080-fcd9-496b-829e-fe27417fec11', $$figuur 2: vierhoek AORS grijs$$,
   $$wiskunde-b-vwo-2024-i-halve-cirkel-context4.png$$,
   $$figuur 2: halve cirkel c met driehoek BRO en de grijze vierhoek AORS$$, 'inline'),
  ('86741efc-df5f-4411-b538-9c9620f45874', 'bffaeadf-2c7d-4818-86b4-862a50434fa7', $$fₐ(x) = (ax² − 2)/(x² + a); geen waarde van a geeft een perforatie$$,
   $$wiskunde-b-vwo-2024-i-top-asymptoot-en-geen-perforatie-context1.png$$,
   $$Voor elke waarde van a wordt de functie fₐ gegeven door:
fₐ(x) = (ax² − 2)/(x² + a)
Er bestaat geen waarde van a waarvoor de grafiek van fₐ een perforatie heeft.$$, 'inline'),
  ('dc013953-0048-4cdd-999f-e9bd307407a0', 'bffaeadf-2c7d-4818-86b4-862a50434fa7', $$a > 0: top T op de y-as, horizontale asymptoot snijdt de y-as in S$$,
   $$wiskunde-b-vwo-2024-i-top-asymptoot-en-geen-perforatie-context2.png$$,
   $$In het volgende onderdeel zijn de mogelijke waarden van a de positieve getallen, dus a > 0.
De grafiek van fₐ heeft één top T en deze ligt op de y-as. Verder heeft de grafiek van fₐ een horizontale asymptoot. Punt S is het snijpunt van de horizontale asymptoot en de y-as. Als voorbeeld is in de figuur de grafiek van f₃ weergegeven.$$, 'inline'),
  ('fe1681d3-c0d9-4485-be22-c892e69a9a5d', 'bffaeadf-2c7d-4818-86b4-862a50434fa7', $$figuur: grafiek van f₃ met S en T$$,
   $$wiskunde-b-vwo-2024-i-top-asymptoot-en-geen-perforatie-context3.png$$,
   $$figuur: de grafiek van f₃ met top T en het punt S op de gestippelde horizontale asymptoot$$, 'inline'),
  ('2abbc15b-c7dc-492d-9e0f-db627d3a310d', 'bffaeadf-2c7d-4818-86b4-862a50434fa7', $$lengte van ST heeft een minimum$$,
   $$wiskunde-b-vwo-2024-i-top-asymptoot-en-geen-perforatie-context4.png$$,
   $$De lengte van lijnstuk ST is afhankelijk van a. Deze lengte heeft een minimum.$$, 'inline'),
  ('d4050ee8-78c0-4aa4-96ad-e50ed1f8f61d', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$inleiding: de Wet van Titius-Bode en het rangnummer van een planeet$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context1.png$$,
   $$De Wet van Titius-Bode¹⁾ is een wet uit de astronomie die door Johann Titius werd opgesteld in de achttiende eeuw. Deze wet legt een verband tussen het rangnummer van een planeet en de afstand van die planeet tot de zon. Met het rangnummer van een planeet wordt bedoeld: ‘de zoveelste planeet geteld vanaf de zon’. De planeet die het dichtst bij de zon staat krijgt nummer 1, de volgende 2 enzovoorts.$$, 'inline'),
  ('85ed5303-0578-43a7-a566-f3787c93c912', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$wet a = 0,4 + 0,3 · 2ⁿ⁻²: a afstand in AE, n rangnummer$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context2.png$$,
   $$De wet luidt:
a = 0,4 + 0,3 · 2ⁿ⁻²
Hierin is a de afstand van de planeet tot de zon uitgedrukt in AE (Astronomische Eenheid, 1 AE = afstand van de aarde tot de zon) en is n het rangnummer van de planeet.$$, 'inline'),
  ('2f807a6a-af8e-4909-9e09-16eac4c5621f', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$Saturnus heeft volgens de wet een afstand van 10 AE$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context3.png$$,
   $$Saturnus heeft volgens de Wet van Titius-Bode een afstand van 10 AE tot de zon.$$, 'inline'),
  ('0ca1f8e6-3ad9-4b5c-8ee3-5f098d5e7877', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$model: cirkelvormige banen van Venus (0,7 AE), aarde (1,0 AE) en Mars (1,6 AE); figuur 1$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context4.png$$,
   $$We bekijken de planeten Mars, Venus en de aarde. We gaan uit van het volgende eenvoudige model:
De drie planeten draaien ieder in een cirkelvormige baan met de zon als middelpunt. De drie banen liggen in één plat vlak.
De afstand van Venus tot de zon is 0,7 AE, de afstand van de aarde tot de zon is 1,0 AE en de afstand van Mars tot de zon is 1,6 AE.
figuur 1 (afstanden in AE): de drie cirkelbanen om Z met M, V en A op één lijn, MV = VA = d en hoek α bij V$$, 'inline'),
  ('19180cfb-f702-4c59-8ac9-79463e7ab90a', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$Venus precies midden tussen Mars en de aarde op één lijn$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context5.png$$,
   $$Het is mogelijk dat de drie planeten op één lijn liggen waarbij Venus precies midden tussen Mars en de aarde in ligt. Deze situatie is weergegeven in figuur 1.$$, 'inline'),
  ('af1ed118-eff7-4d2b-962a-cc5ef942f2d3', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$noot 1 bij de Wet van Titius-Bode$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context6.png$$,
   $$noot 1 Er is geen wetenschappelijke onderbouwing voor deze wet en er wordt tegenwoordig aangenomen dat de wet alleen berust op een toevallige overeenkomst met de werkelijke afstanden.$$, 'inline'),
  ('1d43af55-1a1d-4520-a7f0-0fef2e80d3ef', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$verband tussen d en α: (d² − 0,51)/cos(α) = (d² − 2,07)/cos(180° − α)$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context7.png$$,
   $$De afstand in AE van de aarde tot Venus is d en hoek AVZ in graden is α. Met behulp van figuur 1 kan het volgende verband tussen d en α worden gevonden:
(d² − 0,51)/cos(α) = (d² − 2,07)/cos(180° − α)$$, 'inline'),
  ('624944cd-5153-4053-952d-acbbd1585aa6', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$zon en Jupiter als puntmassa's om hun gemeenschappelijk zwaartepunt; massa's en afstand$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context8.png$$,
   $$Meestal wordt gezegd dat de planeten in ons zonnestelsel om de zon draaien. Dat klopt echter niet helemaal: de zon en de planeten draaien allemaal om hun gemeenschappelijke zwaartepunt.
Stel dat het zonnestelsel alleen zou bestaan uit Jupiter en de zon. We beschouwen deze twee hemellichamen als twee puntmassa''s.
Jupiter is verreweg de zwaarste planeet in ons zonnestelsel met een massa van 2 · 10²⁷ kg en een afstand tot de zon van 8 · 10⁸ km. De zon heeft een massa van 2 · 10³⁰ kg. Zie figuur 2 (niet op schaal).$$, 'inline'),
  ('e2f9f2ca-815f-4a71-bab3-8864d892fea7', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$figuur 2: zon, Jupiter en hun zwaartepunt$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context9.png$$,
   $$figuur 2: zon (massa 2 · 10³⁰ kg) en Jupiter (massa 2 · 10²⁷ kg) op afstand 8 · 10⁸ km, met het zwaartepunt van zon en Jupiter en de kleine cirkelbaan van de zon$$, 'inline'),
  ('65b72769-ab1f-4c13-8f03-eff5bc2396bc', 'e8bad8b0-f73c-4fe6-a8bc-9874ed1c1e69', $$de kleine cirkel is de baan van de zon om het zwaartepunt$$,
   $$wiskunde-b-vwo-2024-i-vereenvoudigde-sterrenkunde-context10.png$$,
   $$De kleine cirkel in figuur 2 is de baan van de zon om het zwaartepunt.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('9b947309-7169-4fc9-b275-ca7af8083964', '543c3607-0021-4864-aca4-912c8ab60fd4', 1,
   '[{"domain": "Differentiaal- en integraalrekening", "subdomain": "Afgeleide functies"}, {"domain": "Differentiaal- en integraalrekening", "subdomain": "Technieken voor differentiëren"}]'::jsonb,
